/// <summary>
/// PaffH 16.01.25
/// last modified: PaffH 20.02.25
/// </summary>
[DataContract]
public class NDXUmsatzClassParmContract extends NDXBatchProcessingTableContract
{
    NDXUmsSignature umsSignature;
    List firmen;
    List companies;
    int anzFirmen;
    int anzCompanies;
    boolean lAlliance;
    CommissSalesGroup salesGroupId;
    int dataVersion;
    NoYes lBasisUmsLfdJ;
    NoYes lCSIncl;
    boolean lSalesGroupMaster;
    int nAnzChilds;
    NDXYear yearlfdJ;
    NDXYear yearVJ;
    NDXMonthYearSignature monthYearSignature;
    boolean lwithProt;
    boolean lUseCalculatedData;
    boolean lGetDataOnly;
    boolean lGetDataPerChild;
    boolean lSalesPerDebitor;
    NDXCompanyBE firma;

}

