/// <summary>
/// PaffH 16.01.25
/// last modified: PaffH 20.02.25
/// </summary>
/// <returns>container</returns>
public container containerFromContract()
{
    container con = conNull();
    con += this.parmUmsSignature();
    con += this.parmLThread();
    con += this.parmLAlliance();
    con += this.parmAccountNum();
    con += this.parmSalesGroupId();
    con += this.parmDataVersion();
    con += this.parmLBasisUmsLfdJ();
    con += this.parmLCSIncl();
    con += this.parmLSalesGroupMaster();
    con += firmen.elements();
    container con2 = conNull();
    ListEnumerator enum = firmen.getEnumerator();
    while (enum.moveNext())
    {
        con2 += enum.current();
    }
    con += con2;
    con += this.parmBatchWithMultithreading();
    con += this.parmBatchMultiThreadingStatus();
    con += this.parmRecIdNDXBatchProcessingTable();

    return con;
}

/// <summary>
/// PaffH 20.10.25
/// last modified: PaffH 20.02.25
/// </summary>
/// <param name = "_con">container</param>
/// <returns>NDXUmsatzClassParmContract</returns>
public static NDXUmsatzClassParmContract contractFromCon(container _con)
{
    int conPos = 0;
    NDXUmsatzClassParmContract contract = NDXUmsatzClassParmContract::construct();
    ++conPos;
    contract.parmUmsSignature(conPeek(_con, conPos));
    ++conPos;
    contract.parmLThread(conPeek(_con, conPos));
    ++conPos;
    contract.parmLAlliance(conPeek(_con, conPos));
    ++conPos;
    contract.parmAccountNum(conPeek(_con, conPos));
    ++conPos;
    contract.parmSalesGroupId(conPeek(_con, conPos));
    ++conPos;
    contract.parmDataVersion(conPeek(_con, conPos));
    ++conPos;
    contract.parmLBasisUmsLfdJ(conPeek(_con, conPos));
    ++conPos;
    contract.parmLCSIncl(conPeek(_con, conPos));
    ++conPos;
    contract.parmLSalesGroupMaster(conPeek(_con, conPos));
    ++conPos;
    int anzFirmen = conPeek(_con, conPos);
    for (int i = 1; i <= anzFirmen; i++)
    {
        ++conPos;
        //contract.parmFirmen().addEnd(NDXFirmaContract::construct(conPeek(_con, conpos)));
        contract.parmFirmen().addEnd(conPeek(_con, conpos));
    }
    ++conPos;
    contract.parmBatchWithMultithreading(conPeek(_con, conPos));
    ++conPos;
    contract.parmBatchMultiThreadingStatus(conPeek(_con, conpos));
    ++conPos;
    contract.parmRecIdNDXBatchProcessingTable(conPeek(_con, conpos));
    return contract;

}

