    con += [[NDXUmsatzConstants::lGetDataPerChild, this.parmLGetDataPerChild()]];
    con += [[NDXUmsatzConstants::LThread, this.parmLThread()]];
    con += [[NDXUmsatzConstants::lAlliance, this.parmLAlliance()]];
    con += [[NDXUmsatzConstants::SalesGroupId, this.parmSalesGroupId()]];
    con += [[NDXUmsatzConstants::lSalesGroupMaster, this.parmLSalesGroupMaster()]];
    con += [[NDXUmsatzConstants::lSalesPerDebitor, this.parmLSalesPerDebitor()]];
    con += [[NDXUmsatzConstants::Firma, this.parmFirma()]];
    con += [[NDXUmsatzConstants::ProcessSignature, this.parmProcessSignature()]];
    con += [[NDXUmsatzConstants::BatchWithMultithreading, this.parmBatchWithMultithreading()]];
    con += [[NDXUmsatzConstants::BatchMultiThreadingStatus, this.parmBatchMultiThreadingStatus()]];
    con += [[NDXUmsatzConstants::RecIdNDXBatchProcessingTable, this.parmRecIdNDXBatchProcessingTable()]];

    return con;
}

