/// <summary>
/// PaffH 20.01.25
/// last modified: PaffH 20.02.25
/// </summary>
/// <param name = "_con2">container with 2 dimensions</param>
/// <returns>NDXUmsatzClassParmContract</returns>
public static NDXUmsatzClassParmContract contractFromCon2Dim(container _con2)
{
    NDXUmsatzClassParmContract nDXUmsatzClassParmContract = NDXUmsatzClassParmContract::construct();
    for(int i = 1; i<= conLen(_con2); i++)
    {
        container conParm = conPeek(_con2, i);

        switch(conPeek(conParm, 1))
        {
            case NDXUmsatzConstants::UmsSignature:
                nDXUmsatzClassParmContract.parmUmsSignature(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::AccountNum:
                nDXUmsatzClassParmContract.parmAccountNum(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::NAnzChilds:
                nDXUmsatzClassParmContract.parmNAnzChilds(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::ConLenFirmen:
                nDXUmsatzClassParmContract.parmAnzFirmen(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::ConFirmen:
                nDXUmsatzClassParmContract.parmFirmen(con2List(conPeek(conParm, 2)));
                break;
            case NDXUmsatzConstants::ConLenCompanies:
                nDXUmsatzClassParmContract.parmAnzCompanies(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::ConCompanies:
                nDXUmsatzClassParmContract.parmCompanies(con2List(conPeek(conParm, 2)));
                break;
            case NDXUmsatzConstants::YearlfdJ:
                nDXUmsatzClassParmContract.parmYearlfdJ(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::MonthYearSignature:
                nDXUmsatzClassParmContract.parmMonthYearSignature(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::YearVJ:
                nDXUmsatzClassParmContract.parmYearVJ(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::LCSIncl:
                nDXUmsatzClassParmContract.parmLCSIncl(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::LwithProt:
                nDXUmsatzClassParmContract.parmLwithProt(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::lUseCalculatedData:
                nDXUmsatzClassParmContract.parmLUseCalculatedData(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::LGetDataOnly:
                nDXUmsatzClassParmContract.parmLGetDataOnly(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::lGetDataPerChild:
                nDXUmsatzClassParmContract.parmLGetDataPerChild(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::LThread:
                nDXUmsatzClassParmContract.parmLThread(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::lAlliance:
                nDXUmsatzClassParmContract.parmLAlliance(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::SalesGroupId:
                nDXUmsatzClassParmContract.parmSalesGroupId(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::lSalesGroupMaster:
                nDXUmsatzClassParmContract.parmLSalesGroupMaster(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::lSalesPerDebitor:
                nDXUmsatzClassParmContract.parmLSalesPerDebitor(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::Firma:
                nDXUmsatzClassParmContract.parmFirma(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::ProcessSignature:
                nDXUmsatzClassParmContract.parmProcessSignature(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::BatchWithMultithreading:
                nDXUmsatzClassParmContract.parmBatchWithMultithreading(conPeek(conParm, 2));
                break;
            case NDXUmsatzConstants::RecIdNDXBatchProcessingTable:
                nDXUmsatzClassParmContract.parmRecIdNDXBatchProcessingTable(conPeek(conParm, 2));
                break;
        }
    }
    return nDXUmsatzClassParmContract;

}

/// <summary>
/// PaffH 16.01.25
/// last modified: PaffH 21.02.25
/// </summary>
/// <param name = "_nDXUmsatzClass">NDXUmsatzClass</param>
/// <returns>NDXUmsatzClassParmContract</returns>
public static NDXUmsatzClassParmContract contractFromNDXUmsatzClass(NDXUmsatzClass _nDXUmsatzClass)
{
    NDXUmsatzClassParmContract contract = NDXUmsatzClassParmContract::construct();
    contract.parmUmsSignature(_nDXUmsatzClass.parmUmsSignature());
    contract.parmLThread(_nDXUmsatzClass.parmLThread());
    contract.parmLAlliance(_nDXUmsatzClass.parmlAlliance());
    contract.parmAccountNum(_nDXUmsatzClass.parmAccountNum());
    contract.parmSalesGroupId(_nDXUmsatzClass.parmSalesGroupId());
    contract.parmDataVersion(_nDXUmsatzClass.parmDataVersion());
    contract.parmLBasisUmsLfdJ(_nDXUmsatzClass.parmlBasisUmsLfdJ());
    contract.parmLCSIncl(_nDXUmsatzClass.parmLCSIncl());
    contract.parmLSalesGroupMaster(_nDXUmsatzClass.parmNDXVerband().parmlSalesGroupMaster());
    contract.parmNAnzChilds(_nDXUmsatzClass.parmNAnzChilds());
    contract.parmYearlfdJ(_nDXUmsatzClass.parmYearlfdJ());
    contract.parmMonthYearSignature(_nDXUmsatzClass.parmMonthYearSignature());
    contract.parmYearVJ(_nDXUmsatzClass.parmYearVJ());
    contract.parmLwithProt(_nDXUmsatzClass.parmLwithProt());
    contract.parmLGetDataOnly(_nDXUmsatzClass.parmLGetDataOnly());
    contract.parmLGetDataPerChild(_nDXUmsatzClass.parmlGetDataPerChild());
    contract.parmLSalesPerDebitor(_nDXUmsatzClass.parmNDXVerband().parmlSalesPerDebitor());
    contract.parmFirma(_nDXUmsatzClass.parmFirma());
    if (_nDXUmsatzClass.parmSignatureCust())
    {
        contract.parmProcessSignature(_nDXUmsatzClass.parmSignatureCust());
    }
    else if (_nDXUmsatzClass.parmSignatureArtGrp())
    {
        contract.parmProcessSignature(_nDXUmsatzClass.parmSignatureArtGrp());
    }
    else if (_nDXUmsatzClass.parmSignatureCS())
    {
        contract.parmProcessSignature(_nDXUmsatzClass.parmSignatureCS());
    }
    contract.parmFirmen(con2List(_nDXUmsatzClass.parmConFirmen()));
    contract.parmCompanies(con2List(_nDXUmsatzClass.parmConCompanies()));
    contract.parmBatchWithMultithreading(_nDXUmsatzClass.parmBatchWithMultiThreading());
    contract.parmRecIdNDXBatchProcessingTable(_nDXUmsatzClass.parmRecIdNDXBatchProcessingTable());
    return contract;
}
